window.ScripturaLexicons.LSJ.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1655\" data-lsj-orig-id=\"n1655\" data-lsj-ordinal=\"1676\"><td class=\"greek\">ἀειφυγία</td><td>LSJ</td><td>Exílio perpétuo, banimento por toda a vida; pena jurídica.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1656\" data-lsj-orig-id=\"n1656\" data-lsj-ordinal=\"1677\"><td class=\"greek\">ἀειφύλακτος</td><td>LSJ</td><td>Glosa equivalente a ἀείφρουρος, sempre vigilante.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1657\" data-lsj-orig-id=\"n1657\" data-lsj-ordinal=\"1678\"><td class=\"greek\">ἀειφυλλία</td><td>LSJ</td><td>Condição de árvore que não perde as folhas; permanência foliar.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1658\" data-lsj-orig-id=\"n1658\" data-lsj-ordinal=\"1679\"><td class=\"greek\">ἀείφυλλος</td><td>LSJ</td><td>Que não perde as folhas, perenifólio.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1659\" data-lsj-orig-id=\"n1659\" data-lsj-ordinal=\"1680\"><td class=\"greek\">ἀείχλωρος</td><td>LSJ</td><td>Sempre verde, de vegetação, inclusive da alcaparreira.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1660\" data-lsj-orig-id=\"n1660\" data-lsj-ordinal=\"1681\"><td class=\"greek\">ἀειχρόνιος</td><td>LSJ</td><td>Eterno, de duração perpétua.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1661\" data-lsj-orig-id=\"n1661\" data-lsj-ordinal=\"1682\"><td class=\"greek\">ἀείχρυσον</td><td>LSJ</td><td>Nome de planta equivalente a ἀείζωον μέγα; identificação botânica no original.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1662\" data-lsj-orig-id=\"n1662\" data-lsj-ordinal=\"1683\"><td class=\"greek\">ἀεκαζόμενος</td><td>LSJ</td><td>Particípio equivalente a ἀέκων, contrariado ou involuntário; glosa adicional ἀέκασσα, «a contragosto».</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1663\" data-lsj-orig-id=\"n1663\" data-lsj-ordinal=\"1684\"><td class=\"greek\">ἀεκήλιος</td><td>LSJ</td><td>Forma variante de ἀεικέλιος, «indecoroso»; etimologia antiga alternativa documentada.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1664\" data-lsj-orig-id=\"n1664\" data-lsj-ordinal=\"1685\"><td class=\"greek\">ἀέκητι</td><td>LSJ</td><td>Contra a vontade de alguém, sem seu consentimento; advérbio épico com genitivo.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1665\" data-lsj-orig-id=\"n1665\" data-lsj-ordinal=\"1686\"><td class=\"greek\">ἀεκούσιος</td><td>LSJ</td><td>Involuntário, forçado, contrário à vontade, de ato ou consequência; em contexto jurídico, delito involuntário; advérbio «involuntariamente».</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1666\" data-lsj-orig-id=\"n1666\" data-lsj-ordinal=\"1687\"><td class=\"greek\">ἀέκων</td><td>LSJ</td><td>Que age contra sua vontade, contrariado, relutante; involuntariamente; forma contraída ática ἄκων e oposição a ἑκών. Exemplos no TEI.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1667\" data-lsj-orig-id=\"n1667\" data-lsj-ordinal=\"1688\"><td class=\"greek\">ἀέλικτος</td><td>LSJ</td><td>Leitura variante de τριέλικτος em oráculo transmitido por Heródoto.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1668\" data-lsj-orig-id=\"n1668\" data-lsj-ordinal=\"1689\"><td class=\"greek\">ἀέλιοι</td><td>LSJ</td><td>Cunhados cujas esposas são irmãs; formas variantes em lexicógrafos.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1669\" data-lsj-orig-id=\"n1669\" data-lsj-ordinal=\"1690\"><td class=\"greek\">ἀέλιος</td><td>LSJ</td><td>Forma dórica de ἠέλιος e ἥλιος, sol; quantidade vocálica conforme a fonte.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1670\" data-lsj-orig-id=\"n1670\" data-lsj-ordinal=\"1691\"><td class=\"greek\">ἄελλα</td><td>LSJ</td><td>Vendaval, vento tempestuoso, redemoinho; figuradamente, movimento giratório; variantes épicas e eólicas.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1671\" data-lsj-orig-id=\"n1671\" data-lsj-ordinal=\"1692\"><td class=\"greek\">ἀελλαῖος</td><td>LSJ</td><td>Veloz como a tempestade, de pomba.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1671a\" data-lsj-orig-id=\"n1671a\" data-lsj-ordinal=\"1693\"><td class=\"greek\">ἀελλάς</td><td>LSJ</td><td>Veloz como a tempestade, de cavalos e vozes; variante do anterior, artigo suplementar.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1672\" data-lsj-orig-id=\"n1672\" data-lsj-ordinal=\"1694\"><td class=\"greek\">ἀελλεῖ</td><td>LSJ</td><td>Glosas de Hesíquio: adular, afagar; noutras formas, girar, assar ou soprar, conforme a leitura.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1673\" data-lsj-orig-id=\"n1673\" data-lsj-ordinal=\"1695\"><td class=\"greek\">ἀελλήεις</td><td>LSJ</td><td>Equivalente a ἀελλαῖος, veloz como a tempestade.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1674\" data-lsj-orig-id=\"n1674\" data-lsj-ordinal=\"1696\"><td class=\"greek\">ἀελλής</td><td>LSJ</td><td>Que gira em redemoinho, de poeira; possível forma contraída de ἀελλήεις.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1675\" data-lsj-orig-id=\"n1675\" data-lsj-ordinal=\"1697\"><td class=\"greek\">ἀελλησιθύμοις</td><td>LSJ</td><td>Glosa textual incerta, talvez ἀελλησιθύμοις; sentido indicado «irresistíveis, com franqueza»; leitura alternativa proposta.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1676\" data-lsj-orig-id=\"n1676\" data-lsj-ordinal=\"1698\"><td class=\"greek\">ἀελλοδρόμας</td><td>LSJ</td><td>Veloz como a tempestade, de potro.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1677\" data-lsj-orig-id=\"n1677\" data-lsj-ordinal=\"1699\"><td class=\"greek\">ἀελλόθριξ</td><td>LSJ</td><td>De cabelos agitados pelo vento, esvoaçantes.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1678\" data-lsj-orig-id=\"n1678\" data-lsj-ordinal=\"1700\"><td class=\"greek\">ἀελλομάχος</td><td>LSJ</td><td>Que luta contra a tempestade ou enfrenta o temporal.</td><td>LSJ</td></tr>";
